txt <- function(x) {
  y <- as.character(x)
  suspicious <- grepl("Ã|Â|â", y)
  if (any(suspicious, na.rm = TRUE)) {
    z <- y[suspicious]
    for (i in seq_len(6L)) {
      zz <- suppressWarnings(iconv(z, from = "latin1", to = "UTF-8"))
      ok <- !is.na(zz)
      z[ok] <- zz[ok]
    }
    z <- gsub("[^A-Za-z0-9 /:;,.()_\\-\\n]", "", z, perl = TRUE)
    fixes <- c(
      "validacin" = "validacion",
      "Validacin" = "Validacion",
      "Versin" = "Version",
      "Propsito" = "Proposito",
      "epidemiolgica" = "epidemiologica",
      "epidemiolgicamente" = "epidemiologicamente",
      "redistribucin" = "redistribucion",
      "correccin" = "correccion",
      "comparacin" = "comparacion",
      "pandmico" = "pandemico",
      "Sntesis" = "Sintesis",
      "sntesis" = "sintesis",
      "presentacin" = "presentacion",
      "rpida" = "rapida",
      "til" = "util",
      "se al" = "senal",
      "ao" = "anio",
      "Ao" = "Anio"
    )
    for (k in names(fixes)) z <- gsub(k, fixes[[k]], z, fixed = TRUE)
    y[suspicious] <- z
  }
  y
}

body_add_par_utf8 <- function(doc, value, style = "Normal") {
  body_add_par(doc, txt(value), style = style)
}

body_add_bullets <- function(doc, lines) {
  for (line in lines) {
    doc <- body_add_par_utf8(doc, paste0("- ", line), style = "Normal")
  }
  doc
}

first_existing <- function(paths) {
  hit <- paths[file.exists(paths)]
  if (length(hit) == 0L) return(NA_character_)
  hit[1]
}

read_dt_any <- function(path) {
  if (exists("read_auto")) return(as.data.table(read_auto(path)))
  ext <- tolower(tools::file_ext(path))
  if (ext == "csv") return(fread(path))
  if (ext == "parquet") return(as.data.table(arrow::read_parquet(path)))
  stop("Formato no soportado: ", path)
}

safe_fread <- function(path) {
  if (!file.exists(path)) return(NULL)
  tryCatch(fread(path), error = function(e) NULL)
}

safe_rate <- function(num, den, mult = 100000) {
  out <- rep(NA_real_, length(num))
  ok <- !is.na(num) & !is.na(den) & den > 0
  out[ok] <- mult * num[ok] / den[ok]
  out
}

label_space_num <- function(accuracy = 1) {
  scales::label_number(accuracy = accuracy, big.mark = " ", decimal.mark = ".")
}

sex_label <- function(x) {
  fifelse(x == CFG$sex_male, "Hombre", fifelse(x == CFG$sex_female, "Mujer", as.character(x)))
}

ft_compact <- function(dt, fontsize = 8.5) {
  flextable(dt) |>
    theme_booktabs() |>
    fontsize(size = fontsize, part = "all") |>
    padding(padding = 3, part = "all") |>
    autofit()
}

fmt_num <- function(x, digits = 1) {
  out <- formatC(as.numeric(x), format = "f", digits = digits, big.mark = " ", decimal.mark = ".")
  out[is.na(x)] <- NA_character_
  out
}

fmt_table_numeric <- function(dt, digits_map = list()) {
  x <- copy(dt)
  for (nm in names(x)[vapply(x, is.numeric, logical(1))]) {
    dig <- if (!is.null(digits_map[[nm]])) digits_map[[nm]] else 1
    x[, (nm) := fmt_num(get(nm), dig)]
  }
  x
}

body_add_ft_safe <- function(doc, title, dt, note = NULL, digits_map = list(), fontsize = 8.5) {
  if (is.null(dt) || !is.data.table(dt) || nrow(dt) == 0L) return(doc)
  doc <- body_add_par_utf8(doc, title, style = "heading 2")
  if (!is.null(note)) doc <- body_add_par_utf8(doc, note, style = "Normal")
  doc <- body_add_flextable(doc, ft_compact(fmt_table_numeric(dt, digits_map), fontsize = fontsize))
  body_add_par_utf8(doc, "", style = "Normal")
}

body_add_figure_safe <- function(doc, title, img_path, note = NULL, width = 6.8, height = 4.4) {
  if (is.null(img_path) || !file.exists(img_path)) return(doc)
  doc <- body_add_par_utf8(doc, title, style = "heading 2")
  if (!is.null(note)) doc <- body_add_par_utf8(doc, note, style = "Normal")
  doc <- body_add_img(doc, src = img_path, width = width, height = height)
  body_add_par_utf8(doc, "", style = "Normal")
}

save_plot_safe <- function(p, path, width = 9, height = 6, dpi = 320) {
  tryCatch({
    ggsave(filename = path, plot = p, width = width, height = height, dpi = dpi, bg = "white")
    TRUE
  }, error = function(e) FALSE)
}

write_csv_safe <- function(x, path) {
  tryCatch({
    fwrite(as.data.table(x), path)
    invisible(path)
  }, error = function(e) NULL)
}

coerce_numeric_cols <- function(dt, cols) {
  x <- copy(as.data.table(dt))
  hits <- intersect(cols, names(x))
  for (nm in hits) x[, (nm) := suppressWarnings(as.numeric(get(nm)))]
  x
}

safe_print_docx <- function(doc, target) {
  tryCatch({
    print(doc, target = target)
    target
  }, error = function(e) {
    msg_txt <- conditionMessage(e)
    if (!grepl("is open", msg_txt, fixed = TRUE)) stop(e)
    alt_target <- file.path(dirname(target), paste0(tools::file_path_sans_ext(basename(target)), "_latest_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".docx"))
    print(doc, target = alt_target)
